function parseReportSocial(r){try{const x=JSON.parse(r?.social_results_json||'[]');return Array.isArray(x)?x:[]}catch{return []}}
const reportMetrics={followers:'Follower',follower_growth_pct:'Crescita follower %',reach:'Reach',views:'Visualizzazioni',interactions:'Interazioni',engagement_rate_pct:'Engagement %',profile_visits:'Visite profilo',clicks:'Click',leads:'Lead'};
const reportPercentMetrics=new Set(['follower_growth_pct','engagement_rate_pct']);
const reportMetricOrder=['followers','follower_growth_pct','reach','views','interactions','engagement_rate_pct','profile_visits','clicks','leads'];
function reportMetricValue(v){const n=Number(v);return Number.isFinite(n)&&n>0?n:null}
function aggregateReport(r,platform='all'){
  let rows=parseReportSocial(r);if(platform!=='all')rows=rows.filter(x=>String(x.platform)===String(platform));
  const out={followers:null,follower_growth_pct:null,reach:null,views:null,interactions:null,engagement_rate_pct:null,profile_visits:null,clicks:null,leads:null};
  for(const k of reportMetricOrder){const vals=rows.map(x=>reportMetricValue(x[k])).filter(v=>v!==null);if(!vals.length)continue;out[k]=reportPercentMetrics.has(k)?vals.reduce((a,b)=>a+b,0)/vals.length:vals.reduce((a,b)=>a+b,0)}
  return out
}
function reportPeriodLabel(v){if(!v)return '—';const [y,m]=String(v).split('-').map(Number);return new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(new Date(y,m-1,1))}
function reportDelta(a,b,percent=false){if(a===null||a===undefined||b===null||b===undefined)return '';const d=Number(a)-Number(b),cls=d>0?'up':d<0?'down':'neutral',txt=(d>0?'+':'')+(percent?d.toFixed(2)+'%':Math.round(d).toLocaleString('it-IT'));return `<span class="report-delta ${cls}">${txt}</span>`}
function formatReportMetric(k,v){if(v===null||v===undefined||Number(v)<=0)return '—';return reportPercentMetrics.has(k)?Number(v).toFixed(2)+'%':Number(v).toLocaleString('it-IT')}
function trendSvg(points,metric){const usable=points.filter(x=>reportMetricValue(x[metric])!==null);if(!usable.length)return '<div class="empty">Nessun valore registrato per questa metrica.</div>';const vals=usable.map(x=>Number(x[metric])),max=Math.max(...vals,1),min=Math.min(...vals),range=Math.max(1,max-min),w=760,h=220,pad=28;const xy=vals.map((v,i)=>({x:usable.length===1?w/2:pad+i*(w-pad*2)/(usable.length-1),y:h-pad-((v-min)/range)*(h-pad*2)}));const poly=xy.map(p=>`${p.x},${p.y}`).join(' ');return `<div class="report-chart-wrap"><svg class="report-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}" class="chart-axis"/><polyline points="${poly}" class="chart-line"/>${xy.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4" class="chart-dot"><title>${reportPeriodLabel(usable[i].period)}: ${formatReportMetric(metric,vals[i])}</title></circle>`).join('')}</svg><div class="report-chart-labels">${usable.map(x=>`<span>${reportPeriodLabel(x.period).split(' ')[0].slice(0,3)}</span>`).join('')}</div></div>`}
function reportPlatforms(items,clientId){const set=new Set();items.filter(x=>String(x.client_id)===String(clientId)).forEach(r=>parseReportSocial(r).forEach(x=>{if(x.platform)set.add(x.platform)}));return [...set]}
function latestPlatformCards(items,clientId){const clientItems=items.filter(x=>String(x.client_id)===String(clientId)).sort((a,b)=>String(a.period).localeCompare(String(b.period)));if(!clientItems.length)return '';const latest=clientItems[clientItems.length-1],rows=parseReportSocial(latest).filter(x=>reportMetricOrder.some(k=>reportMetricValue(x[k])!==null));if(!rows.length)return '';return `<div class="card report-platform-card"><div class="section-title"><div><h2>Statistiche per social</h2><span>${reportPeriodLabel(latest.period)} · ogni piattaforma resta separata</span></div></div><div class="report-platform-grid">${rows.map(x=>{const metrics=reportMetricOrder.filter(k=>reportMetricValue(x[k])!==null);return `<div class="report-platform-box"><div class="report-platform-title">${esc(x.platform||'Profilo')}</div><div class="report-platform-metrics">${metrics.map(k=>`<div><span>${reportMetrics[k]}</span><b>${formatReportMetric(k,x[k])}</b></div>`).join('')}</div></div>`}).join('')}</div></div>`}
function reportTrendPanel(items,clientId,metric='reach',platform='all'){
  const base=items.filter(x=>String(x.client_id)===String(clientId)).sort((a,b)=>String(a.period).localeCompare(String(b.period)));
  if(!base.length)return '<div class="card report-trend-card"><div class="empty">Nessun dato mensile registrato per questo cliente.</div></div>';
  const platforms=reportPlatforms(items,clientId);
  const rows=base.map(r=>({period:r.period,...aggregateReport(r,platform)}));
  const availableMetrics=reportMetricOrder.filter(k=>rows.some(x=>reportMetricValue(x[k])!==null));
  if(!availableMetrics.includes(metric))metric=availableMetrics[0]||'reach';
  const latest=rows[rows.length-1],prev=rows.length>1?rows[rows.length-2]:null;
  const latestMetrics=availableMetrics.filter(k=>reportMetricValue(latest[k])!==null);
  const tableMetrics=availableMetrics;
  const summaryTitle=platform==='all'?'Riepilogo completo di tutti i social':`Andamento ${platform}`;
  const latestGrid=latestMetrics.length?`<div class="report-latest-grid">${latestMetrics.map(k=>`<div class="report-latest"><span>${reportMetrics[k]}</span><strong>${formatReportMetric(k,latest[k])}</strong>${reportDelta(latest[k],prev?.[k],reportPercentMetrics.has(k))}</div>`).join('')}</div>`:'<div class="empty">Nessun valore maggiore di zero registrato nel mese selezionato.</div>';
  const table=tableMetrics.length?`<div class="table-wrap" style="margin-top:12px"><table class="table"><thead><tr><th>Mese</th>${tableMetrics.map(k=>`<th>${reportMetrics[k]}</th>`).join('')}</tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${reportPeriodLabel(x.period)}</td>${tableMetrics.map(k=>`<td>${formatReportMetric(k,x[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';
  return `${platform==='all'?latestPlatformCards(items,clientId):''}<div class="card report-trend-card" style="margin-top:16px"><div class="section-title"><div><h2>${summaryTitle}</h2><span>${reportPeriodLabel(latest.period)} · i valori a 0 non vengono mostrati</span></div><div class="report-filter-group"><select id="reportPlatform" class="select report-platform-select"><option value="all" ${platform==='all'?'selected':''}>Tutti i social</option>${platforms.map(p=>`<option value="${esc(p)}" ${p===platform?'selected':''}>${esc(p)}</option>`).join('')}</select>${availableMetrics.length?`<select id="reportMetric" class="select report-metric-select">${availableMetrics.map(k=>`<option value="${k}" ${k===metric?'selected':''}>${reportMetrics[k]}</option>`).join('')}</select>`:''}</div></div>${latestGrid}${availableMetrics.length?`<div id="reportTrendChart">${trendSvg(rows,metric)}</div>`:''}${table}</div>`;
}
